INSERT INTO "style" ("id", "name", "prompt", "active", "example_image_url") VALUES ('simple', 'Simple', 'The illustration style is clean flat vector art: solid colour shapes with no outlines, no textures and no gradients beyond a very soft background fade. A restrained palette led by saturated cobalt blue and pale sky-blue tints, with near-black, white and warm terracotta skin tones, plus one or two small accent colours such as green, coral or orange. Each form uses a base colour and a single darker, hard-edged shadow shape of the same hue. No soft shading. People are stylised and slightly elongated, with simplified faces, solid-shape hair and simple but expressive hands. Objects are geometric with rounded corners, often in a gentle three-quarter view. Bold, tightly cropped compositions on a plain white or flat light-blue background with generous negative space.', false, NULL);
